import sys,json,copy

class PredictionError(Exception):
    pass

def fail(message):
    raise PredictionError(message)

def integer(x):
    return type(x) is int

def need(mapping,key,typ):
    if not isinstance(mapping,dict) or key not in mapping:
        fail('unknown: missing '+key)
    value=mapping[key]
    valid=integer(value) if typ is int else isinstance(value,typ)
    if not valid:
        fail('invalid '+key)
    return value

def snapshot(s):
    rev=need(s,'revision',int)
    caps=need(s,'capacities',dict)
    rs=need(s,'reservations',dict)
    tasks=need(s,'tasks',dict)
    ids=need(s,'request_ids',list)
    if any(not isinstance(x,str) for x in ids):
        fail('invalid request_ids')
    for slot,capacity in caps.items():
        if not isinstance(slot,str) or not integer(capacity) or capacity<=0:
            fail('invalid capacities')
    for rid,r in rs.items():
        if not isinstance(rid,str) or not isinstance(r,dict):
            fail('invalid reservations')
        slot=need(r,'slot',str)
        units=need(r,'units',int)
        if units<=0 or slot not in caps:
            fail('invalid reservation')
    return rev,caps,rs,tasks,ids

def step(s,op):
    path=need(op,'path',str)
    body=need(op,'body',dict)
    if path=='/validate':
        operations=need(body,'operations',list)
        if set(body)!={'operations'}:
            fail('unknown: unspecified validate fields')
        trial=copy.deepcopy(s)
        for index,child in enumerate(operations):
            try:
                trial=step(trial,child)
            except PredictionError as e:
                fail('validation step '+str(index)+': '+str(e))
        return s
    if path in ('/state','/contract','/deliveries'):
        if body:
            fail('unknown: read body semantics are unspecified')
        # Predict only absence of effects, not any observed response.
        return s
    fields={
        '/reserve':{'id','slot','units','task_id','request_id','expected_revision'},
        '/move':{'id','slot','task_id','request_id','expected_revision'},
        '/release':{'id','task_id','request_id','expected_revision'},
        '/deliver':{'task_id','text','audience','request_id'}
    }
    if path not in fields:
        fail('unknown: unsupported path')
    request=need(body,'request_id',str)
    rev,caps,rs,tasks,ids=snapshot(s)
    if request in ids:
        fail('unknown: reused request_id requires authoritative exact-request/response reconciliation')
    missing=fields[path]-set(body)
    if missing:
        fail('unknown: missing body fields '+','.join(sorted(missing)))
    if set(body)-fields[path]:
        fail('unknown: unspecified body fields')
    task_id=need(body,'task_id',str)
    if task_id not in tasks:
        fail('task not found')
    task=tasks[task_id]
    stopped=need(task,'stopped',bool)
    if stopped:
        fail('task stopped')
    if path=='/deliver':
        audience=need(body,'audience',str)
        need(body,'text',str)
        original=need(task,'audience',str)
        if audience!=original:
            fail('audience mismatch')
        fail('unknown: independent observation of requested state and audience-safe text cannot be established from this snapshot')
    expected=need(body,'expected_revision',int)
    if expected!=rev:
        fail('stale expected_revision')
    rid=need(body,'id',str)
    authorized=need(task,'authorized_ids',list)
    if any(not isinstance(x,str) for x in authorized):
        fail('invalid authorized_ids')
    if rid not in authorized:
        fail('unauthorized id')
    if path=='/reserve':
        if rid in rs:
            fail('reservation already exists')
        units=need(body,'units',int)
        if units<=0:
            fail('units must be a positive integer')
    else:
        if rid not in rs:
            fail('reservation not found')
        units=rs[rid]['units']
    if path in ('/reserve','/move'):
        slot=need(body,'slot',str)
        if slot not in caps:
            fail('slot not found')
        used=sum(r['units'] for key,r in rs.items() if r['slot']==slot and not (path=='/move' and key==rid))
        if used+units>caps[slot]:
            fail('insufficient capacity')
    # Commit only after all supported preconditions pass, always on a copy.
    out=copy.deepcopy(s)
    if path=='/release':
        del out['reservations'][rid]
    else:
        out['reservations'][rid]={'slot':slot,'units':units}
    out['revision']=rev+1
    out['request_ids'].append(request)
    return out

def predict(data):
    original=data.get('state',{}) if isinstance(data,dict) else {}
    state=copy.deepcopy(original)
    if not isinstance(state,dict) or type(state.get('version')) is not int or state.get('version')!=1:
        return {'unsupported':True,'steps':[],'state':state}
    operations=data.get('operations')
    if not isinstance(operations,list):
        return {'unsupported':False,'steps':[{'ok':False,'error':'unknown: operations list required'}],'state':state}
    steps=[]
    for operation in operations:
        try:
            candidate=step(copy.deepcopy(state),operation)
        except PredictionError as e:
            steps.append({'ok':False,'error':str(e)})
            break
        except RecursionError:
            steps.append({'ok':False,'error':'unknown: validation nesting exceeds predictor limits'})
            break
        state=candidate
        steps.append({'ok':True})
    return {'unsupported':False,'steps':steps,'state':state}

if __name__=='__main__':
    data=json.loads(sys.stdin.read())
    print(json.dumps(predict(data),ensure_ascii=True))
